const proposedSearchJs = `/**
 * Cinejoy webOS - Search View Controller & Virtual Keyboard
 * File: app/js/views/search.js
 * Standard: 10-Foot Television UX, webOS 8.5.0 (Chromium ~108+)
 */

(function (global) {
  'use strict';

  var CardFactory = global.CardFactory;

  var SearchViewController = {
    initialized: false,
    query: '',
    debounceTimer: null,
    isTrapped: false,

    container: null,
    inputDisplay: null,
    placeholder: null,
    resultsGrid: null,
    resultsCount: null,
    keyboard: null,
    clearBtn: null,
    _searchRequestId: 0,

    init: function () {
      if (this.initialized) return;
      this.initialized = true;

      this.container = document.getElementById('view-search');
      if (!this.container) return;

      this.inputDisplay = document.getElementById('search-query-text');
      this.placeholder = document.getElementById('search-query-placeholder');
      this.resultsGrid = document.getElementById('search-results-grid');
      this.resultsCount = document.getElementById('search-results-count');
      this.keyboard = this.container.querySelector('.tv-keyboard-container');
      this.clearBtn = document.getElementById('search-clear-btn');

      this.bindKeyboard();
    },

    bindKeyboard: function () {
      var self = this;
      if (!this.keyboard || this.keyboard._hasBoundSearch) return;
      this.keyboard._hasBoundSearch = true;

      this.keyboard.addEventListener('click', function (e) {
        var keyBtn = e.target.closest('.key-btn');
        if (!keyBtn) return;

        var keyVal = keyBtn.getAttribute('data-key');
        if (keyVal === 'BACKSPACE') {
          self.query = self.query.slice(0, -1);
        } else if (keyVal === 'CLEAR') {
          self.query = '';
        } else if (keyVal === 'SPACE') {
          self.query += ' ';
        } else if (keyVal) {
          self.query += keyVal;
        }

        self.updateInputDisplay();
        self.scheduleSearch();
      });

      // SpatialNav deadend down from bottom row of keyboard escapes to search results
      if (global.SpatialNav && typeof global.SpatialNav.on === 'function') {
        global.SpatialNav.on('deadend', function (data) {
          if (!data) return;
          var curView = (global.CinejoyApp && global.CinejoyApp.state && global.CinejoyApp.state.currentView) || 'search';
          if (curView === 'search' && data.direction === 'down') {
            if (data.element && data.element.closest('.tv-keyboard-container')) {
              self.jumpToResults();
            }
          }
        });
      }

      // Also listen on keydown on the keyboard buttons: ArrowDown from SPACE/CLEAR/DELETE escapes
      this.keyboard.addEventListener('keydown', function (e) {
        if (e.key === 'ArrowDown') {
          var target = e.target.closest('.key-btn');
          if (target) {
            var row = target.closest('.keyboard-row');
            var isBottomRow = row && (!row.nextElementSibling || row.classList.contains('keyboard-row-actions') || target.classList.contains('key-space') || target.classList.contains('key-action'));
            if (isBottomRow) {
              e.preventDefault();
              self.jumpToResults();
            }
          }
        }
      });
    },

    activate: function () {
      this.init();
      this.engageTrap();
      if (!this.query && this.keyboard && global.SpatialNav) {
        var firstKey = this.keyboard.querySelector('[data-key="Q"]') || this.keyboard.querySelector('.key-btn');
        if (firstKey) {
          global.SpatialNav.setFocus(firstKey);
        }
      }
    },

    deactivate: function () {
      this.releaseTrap();
      if (this.debounceTimer) {
        clearTimeout(this.debounceTimer);
        this.debounceTimer = null;
      }
    },

    engageTrap: function () {
      if (global.SpatialNav && this.keyboard && typeof global.SpatialNav.trap === 'function') {
        global.SpatialNav.trap(this.keyboard);
        this.isTrapped = true;
      }
    },

    releaseTrap: function () {
      if (global.SpatialNav && this.isTrapped && typeof global.SpatialNav.untrap === 'function') {
        global.SpatialNav.untrap();
        this.isTrapped = false;
      }
    },

    jumpToResults: function () {
      if (!this.resultsGrid) {
        this.resultsGrid = document.getElementById('search-results-grid');
      }
      if (!this.resultsGrid) return;

      var firstCard = this.resultsGrid.querySelector('.card-poster[data-nav="true"]');
      if (firstCard && global.SpatialNav) {
        this.releaseTrap();
        global.SpatialNav.setFocus(firstCard);
      }
    },

    updateInputDisplay: function () {
      if (!this.inputDisplay) {
        this.inputDisplay = document.getElementById('search-query-text');
      }
      if (!this.placeholder) {
        this.placeholder = document.getElementById('search-query-placeholder');
      }

      if (this.inputDisplay) {
        this.inputDisplay.textContent = this.query;
      }
      if (this.placeholder) {
        this.placeholder.style.display = this.query.length > 0 ? 'none' : 'inline';
      }

      if (global.CinejoyApp && global.CinejoyApp.state) {
        global.CinejoyApp.state.searchQuery = this.query;
      }
    },

    scheduleSearch: function () {
      var self = this;
      if (this.debounceTimer) {
        clearTimeout(this.debounceTimer);
      }

      var clean = this.query.trim();
      if (!clean) {
        this._searchRequestId = (this._searchRequestId || 0) + 1;
        this.renderResults([]);
        if (this.resultsCount) this.resultsCount.textContent = '';
        return;
      }

      this.debounceTimer = setTimeout(function () {
        self.executeSearch();
      }, 300);
    },

    executeSearch: function () {
      var self = this;
      var cleanQuery = this.query.trim();
      if (!cleanQuery) return;

      if (!global.TmdbClient) {
        console.warn('[SearchViewController] TmdbClient unavailable for search.');
        return;
      }

      this._searchRequestId = (this._searchRequestId || 0) + 1;
      var reqId = this._searchRequestId;

      return global.TmdbClient.searchMulti(cleanQuery, 1).then(function (res) {
        if (reqId !== self._searchRequestId || self.query.trim() !== cleanQuery || !self.query.trim()) {
          return;
        }

        if (!res || res.error) {
          self.renderError();
          return;
        }

        var results = res.results || [];
        var filtered = results.filter(function (item) {
          return item.media_type === 'movie' || item.media_type === 'tv' || item.type === 'movie' || item.type === 'tv' || (!item.media_type && (item.title || item.name));
        });

        self.renderResults(filtered);
        if (self.resultsCount) {
          self.resultsCount.textContent = '(' + filtered.length + ' matches)';
        }
      }).catch(function (err) {
        if (reqId !== self._searchRequestId || self.query.trim() !== cleanQuery || !self.query.trim()) {
          return;
        }
        console.error('[SearchViewController] Multi-search failed:', err);
        self.renderError();
      });
    },

    renderResults: function (items) {
      if (!this.resultsGrid) {
        this.resultsGrid = document.getElementById('search-results-grid');
      }
      if (!this.resultsGrid) return;

      while (this.resultsGrid.firstChild) {
        this.resultsGrid.removeChild(this.resultsGrid.firstChild);
      }

      if (items.length === 0 && this.query.trim().length > 0) {
        var emptyDiv = document.createElement('div');
        emptyDiv.className = 'search-empty-state';
        emptyDiv.style.gridColumn = '1 / -1';
        emptyDiv.style.padding = '48px';
        emptyDiv.style.textAlign = 'center';
        emptyDiv.style.color = 'rgba(255, 255, 255, 0.6)';

        var p1 = document.createElement('p');
        p1.style.fontSize = '24px';
        p1.style.fontWeight = '500';
        p1.textContent = 'No results found for "' + this.query + '"';

        var p2 = document.createElement('p');
        p2.style.fontSize = '16px';
        p2.style.marginTop = '8px';
        p2.textContent = 'Check spelling or try searching for another movie or television series.';

        emptyDiv.appendChild(p1);
        emptyDiv.appendChild(p2);
